INSERT INTO posts (slug,title,excerpt,content,status,published_at,created_at,updated_at) VALUES ('a-career-without-apology','On building a career you never have to apologize for','For years I softened every ask and explained every absence. What changed was not my confidence, but my understanding of what I was actually offering.','<p>This is a sample essay so you can see how the journal looks with a few posts in it. Sign in at /admin to edit it, or delete it when you write your own.</p><h2>A heading looks like this</h2><p>Body text is set in Cormorant Garamond, with <strong>bold</strong>, <em>italic</em> and <a href="https://example.com">links</a> in a soft rose.</p><ul><li>Bulleted lists use a small gold diamond</li><li>So they feel at home on the page</li></ul><blockquote><p>You can carry where you come from, and still choose where you are going.</p></blockquote><p>And a closing paragraph to finish the thought.</p>','published',1790603600,1790603600,1790603600);
